static bool g_restorerShareRegistry=false;
static bool g_restorerSharedOpen=false;
static bool g_restorerSharedQuery=false;

// This mod targets the Windows 10+ shell. Set the SDK target before the first
// Windows header so IP Helper's Vista/XP declarations are available consistently.
#ifndef _WIN32_WINNT
#ifdef WINVER
#define _WIN32_WINNT WINVER
#else
#define _WIN32_WINNT 0x0A00
#endif
#endif
#ifndef WINVER
#define WINVER _WIN32_WINNT
#endif
// IP_ADAPTER_ADDRESSES uses SOCKET_ADDRESS from Winsock2; include this before
// headers such as xamlom.h/windows.h that may otherwise pull in legacy winsock.h.
// The Windhawk build preludes windows.h, so this header is necessarily included
// after it and its own "include winsock2.h before windows.h" note cannot be
// avoided from here: it is silenced around this include only, while the Winsock2
// declarations are still taken from it.
#if defined(__clang__)
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-W#warnings"
#endif
#include <winsock2.h>
#if defined(__clang__)
#pragma clang diagnostic pop
#endif
#include <xamlom.h>

#include <atomic>
#include <array>
#include <vector>

// The default log level is intentionally quiet. Detailed visual-tree/property
// traces remain available through the opt-in Windhawk setting.
static std::atomic<bool> g_verboseDiagnostics{false};
#define RESTORER_VERBOSE_LOG(...) \
    do { \
        if (g_verboseDiagnostics.load(std::memory_order_relaxed)) { \
            Wh_Log(__VA_ARGS__); \
        } \
    } while (0)

#undef GetCurrentTime

// >>> win10-skin: include Windows.Foundation.Collections.h before Xaml <<<
#include <winrt/Windows.Foundation.h>
#include <winrt/Windows.Foundation.Collections.h>
// <<< win10-skin: include Windows.Foundation.Collections.h before Xaml <<<
#include <winrt/Windows.UI.Xaml.h>

struct ThemeTargetStyles {
    PCWSTR target;
    std::vector<PCWSTR> styles;
};

enum class DisableNewStartMenuLayout {
    windowsDefault,
    disableNewLayoutAndPhoneLink,
    disableNewLayoutKeepPhoneLink,
    forceNewLayout,
    newLayoutSideBySide,
};

struct Theme {
    std::vector<ThemeTargetStyles> targetStyles;
    std::vector<PCWSTR> styleConstants;
    std::vector<PCWSTR> themeResourceVariables;
    std::vector<ThemeTargetStyles> webViewTargetStyles;
    DisableNewStartMenuLayout startMenuLayout =
        DisableNewStartMenuLayout::windowsDefault;
};

