std::wstring EscapeJsTemplateString(std::wstring_view str) {
    std::wstring buffer;
    buffer.reserve(str.size());
    for (const auto c : str) {
        switch (c) {
            case '\\':
                buffer.append(L"\\\\");
                break;
            case '`':
                buffer.append(L"\\`");
                break;
            default:
                buffer.push_back(c);
                break;
        }
    }

    return buffer;
}

std::wstring CreateWebViewJsCodeForApply() {
    std::wstring jsCode =
        LR"(
        (() => {
        const styleElementId = "windhawk-windows-11-start-menu-styler-style";
        const styleContent = `
    )";

    jsCode += EscapeJsTemplateString(g_webContentCss);

    jsCode +=
        LR"(
        `;
        if (!document.getElementById(styleElementId)) {
            const style = document.createElement("style");
            style.id = styleElementId;
            style.textContent = styleContent;
            document.head.appendChild(style);
        }
    )";

    jsCode += g_webContentJs;

    jsCode +=
        LR"(
        })();
    )";

    if (g_verboseDiagnostics.load(std::memory_order_relaxed)) {
        Wh_Log(L"======================================== JS:");
        std::wstringstream ss(jsCode);
        std::wstring line;
        while (std::getline(ss, line, L'\n')) {
            Wh_Log(L"%s", line.c_str());
        }
        Wh_Log(L"========================================");
    }

    return jsCode;
}

bool ApplyWebViewStyleCustomizations(Controls::WebView webViewElement) {
    auto source = webViewElement.Source();
    if (!source) {
        return false;
    }

    auto canonicalUri = source.AbsoluteCanonicalUri();
    Wh_Log(L"WebView source: %s", canonicalUri.c_str());

    if (canonicalUri != L"https://www.bing.com/WS/Init" &&
        // Offline content (DisableSearchBoxSuggestions registry option).
        canonicalUri !=
            L"ms-appx-web://microsoftwindows.client.cbs/Cortana.UI/cache/"
            L"svlocal/desktop/2.html" &&
        // Windows 10 (SearchApp.exe).
        canonicalUri !=
            L"https://www.bing.com/AS/API/WindowsCortanaPane/V2/Init" &&
        canonicalUri !=
            L"ms-appx-web://microsoft.windows.search/cache/local/desktop/"
            L"2.html") {
        return false;
    }

    std::wstring jsCode = CreateWebViewJsCodeForApply();

    webViewElement.InvokeScriptAsync(
        L"eval", winrt::single_threaded_vector<winrt::hstring>(
                     {winrt::hstring(jsCode.c_str(), jsCode.size())}));

    return true;
}

bool ApplyWebView2StyleCustomizations(
    WebView2Standalone_IWebView2* webViewElement) {
    void* sourcePtr;
    winrt::check_hresult(webViewElement->get_Source(&sourcePtr));
    auto source = winrt::Windows::Foundation::Uri{
        sourcePtr, winrt::take_ownership_from_abi};
    if (!source) {
        return false;
    }

    auto canonicalUri = source.AbsoluteCanonicalUri();
    Wh_Log(L"WebView source: %s", canonicalUri.c_str());

    if (canonicalUri != L"https://www.bing.com/WS/Init" &&
        // Offline content (DisableSearchBoxSuggestions registry option).
        canonicalUri !=
            L"https://searchapp.bundleassets.example/desktop/2.html") {
        return false;
    }

    std::wstring jsCode = CreateWebViewJsCodeForApply();

    void* operationPtr;
    auto jsCodeHstring = winrt::hstring(jsCode.c_str(), jsCode.size());
    winrt::check_hresult(webViewElement->ExecuteScriptAsync(
        *(void**)(&jsCodeHstring), &operationPtr));
    auto operation =
        winrt::Windows::Foundation::IAsyncOperation<winrt::hstring>{
            operationPtr, winrt::take_ownership_from_abi};

    return true;
}

void ApplyCustomizationsIfWebView(InstanceHandle handle,
                                  FrameworkElement element) {
    auto className = winrt::get_class_name(element);
    if (className == L"Windows.UI.Xaml.Controls.WebView") {
        auto& webViewCustomizationState = g_webViewsCustomizationState[handle];
        if (!webViewCustomizationState.element.get()) {
            webViewCustomizationState.element = element;

            auto webViewElement = element.as<Controls::WebView>();

            ApplyWebViewStyleCustomizations(webViewElement);

            webViewCustomizationState.navigationCompletedEventToken =
                webViewElement.NavigationCompleted(
                    [](const Controls::WebView& sender,
                       const Controls::WebViewNavigationCompletedEventArgs&
                           args) {
                        if (args.IsSuccess()) {
                            ApplyWebViewStyleCustomizations(sender);
                        }
                    });
        }
    } else if (className == L"WebView2Standalone.Controls.WebView2") {
        auto& webViewCustomizationState = g_webViewsCustomizationState[handle];
        if (!webViewCustomizationState.element.get()) {
            webViewCustomizationState.element = element;
            webViewCustomizationState.isWebView2 = true;

            winrt::com_ptr<WebView2Standalone_IWebView2> webViewElement;
            winrt::check_hresult(
                ((IUnknown*)winrt::get_abi(element))
                    ->QueryInterface(IID_WebView2Standalone_IWebView2,
                                     webViewElement.put_void()));

            ApplyWebView2StyleCustomizations(webViewElement.get());

            winrt::Windows::Foundation::TypedEventHandler<
                winrt::Windows::Foundation::IInspectable,
                winrt::Windows::Foundation::IInspectable>
                eventHandler = [](const winrt::Windows::Foundation::
                                      IInspectable& sender,
                                  const winrt::Windows::Foundation::
                                      IInspectable& args) {
                    try {
                        winrt::com_ptr<
                            ICoreWebView2NavigationCompletedEventArgs>
                            webViewArgs;
                        winrt::check_hresult(
                            ((IUnknown*)winrt::get_abi(args))
                                ->QueryInterface(
                                    IID_ICoreWebView2NavigationCompletedEventArgs,
                                    webViewArgs.put_void()));

                        bool success = false;
                        winrt::check_hresult(
                            webViewArgs->get_IsSuccess(&success));
                        if (!success) {
                            return;
                        }

                        winrt::com_ptr<WebView2Standalone_IWebView2>
                            webViewElement;
                        winrt::check_hresult(
                            ((IUnknown*)winrt::get_abi(sender))
                                ->QueryInterface(
                                    IID_WebView2Standalone_IWebView2,
                                    webViewElement.put_void()));

                        ApplyWebView2StyleCustomizations(webViewElement.get());
                    } catch (...) {
                    }
                };

            winrt::check_hresult(webViewElement->add_NavigationCompleted(
                *(void**)(&eventHandler),
                put_abi(
                    webViewCustomizationState.navigationCompletedEventToken)));
        }
    }
}

PCWSTR CreateWebViewJsCodeForClear() {
    PCWSTR jsCode =
        LR"(
        (() => {
        const styleElementId = "windhawk-windows-11-start-menu-styler-style";
        const style = document.getElementById(styleElementId);
        if (style) {
            style.parentNode.removeChild(style);
        }
        })();
    )";

    if (g_verboseDiagnostics.load(std::memory_order_relaxed)) {
        Wh_Log(L"======================================== JS:");
        std::wstringstream ss(jsCode);
        std::wstring line;
        while (std::getline(ss, line, L'\n')) {
            Wh_Log(L"%s", line.c_str());
        }
        Wh_Log(L"========================================");
    }

    return jsCode;
}

void ClearWebViewStyleCustomizations(Controls::WebView webViewElement) {
    PCWSTR jsCode = CreateWebViewJsCodeForClear();

    webViewElement.InvokeScriptAsync(
        L"eval", winrt::single_threaded_vector<winrt::hstring>(
                     {winrt::hstring(jsCode)}));
}

void ClearWebView2StyleCustomizations(
    WebView2Standalone_IWebView2* webViewElement) {
    PCWSTR jsCode = CreateWebViewJsCodeForClear();

    void* operationPtr;
    auto jsCodeHstring = winrt::hstring(jsCode);
    winrt::check_hresult(webViewElement->ExecuteScriptAsync(
        *(void**)(&jsCodeHstring), &operationPtr));
    auto operation =
        winrt::Windows::Foundation::IAsyncOperation<winrt::hstring>{
            operationPtr, winrt::take_ownership_from_abi};
}

void ClearWebViewCustomizations(
    const WebViewCustomizationState& webViewCustomizationState) {
    auto element = webViewCustomizationState.element.get();
    if (!element) {
        return;
    }

    if (!webViewCustomizationState.isWebView2) {
        auto webViewElement = element.as<Controls::WebView>();

        ClearWebViewStyleCustomizations(webViewElement);

        webViewElement.NavigationCompleted(
            webViewCustomizationState.navigationCompletedEventToken);
    } else {
        winrt::com_ptr<WebView2Standalone_IWebView2> webViewElement;
        winrt::check_hresult(
            ((IUnknown*)winrt::get_abi(element))
                ->QueryInterface(IID_WebView2Standalone_IWebView2,
                                 webViewElement.put_void()));

        ClearWebView2StyleCustomizations(webViewElement.get());

        winrt::check_hresult(webViewElement->remove_NavigationCompleted(
            webViewCustomizationState.navigationCompletedEventToken));
    }
}

void MergeResourceVariables();

// === Separate pinned items scroll ===
//
// When the user selects the `newLayoutSideBySide` variant of
// `disableNewStartMenuLayout`, the pinned items header, the show-more-pinned
// button, the pinned tiles, and the recommended panel are reparented from
// the apps list's ScrollViewer into a new ScrollViewer that lives as a
// sibling of the apps ScrollViewer. Final structure under
// `GridView#AllAppsGrid > Border`:
//
//   Border > Grid#SideBySidePinnedWrapper
//              > ScrollViewer (original, scrolls the apps list)
//              > ScrollViewer#SideBySidePinnedScrollViewer
//                  > Grid#SideBySidePinnedContent
//                      > Grid#PinnedListHeaderGrid (moved)
//                      > Grid#ShowMorePinnedGrid (moved)
//                      > StartMenu.PinnedList#StartMenuPinnedList (moved)
//                      > Grid#TopLevelSuggestionsRoot (moved)
//
// The wrapper and the new ScrollViewer/content grid are named so users can
// target them from yaml to position and size the pinned panel. The
// reparenting is idempotent and deferred to the next dispatcher tick to
// avoid re-entering the visual tree watcher mid-mutation.

constexpr WCHAR kSeparatePinnedWrapperName[] = L"SideBySidePinnedWrapper";
constexpr WCHAR kSeparatePinnedScrollName[] = L"SideBySidePinnedScrollViewer";
constexpr WCHAR kSeparatePinnedContentName[] = L"SideBySidePinnedContent";

// Tracking for dynamic enable/disable. We remember each restructured Border
// (so we can revert it on toggle-off) and a weak ref to the source
// TopLevelHeader (so revert can move the children back without re-walking
// the visual tree to find it). Entries survive across Initialize/Uninitialize
// cycles and are only cleared by `RevertAllSeparatePinnedScroll`. The
// RestorerSkin_SettingsChanged path uses this to undo the tree mutation when the
// user disables the setting at runtime.
struct SeparatePinnedScrollEntry {
    winrt::weak_ref<Controls::Border> border;
    winrt::weak_ref<Controls::Grid> sourceTopLevelHeader;
};
std::vector<SeparatePinnedScrollEntry> g_separatePinnedScrollEntries;

std::vector<winrt::Windows::Foundation::IAsyncOperation<bool>>
    g_separatePinnedScrollPendingActions;

bool IsSeparatePinnedScrollTargetName(winrt::hstring const& name) {
    return name == L"PinnedListHeaderGrid" || name == L"ShowMorePinnedGrid" ||
           name == L"StartMenuPinnedList" || name == L"TopLevelSuggestionsRoot";
}

// Walk the visual tree below `root` and return the first FrameworkElement
// whose Name matches `name` and that casts to Grid. Used to (re-)locate the
// original Grid#TopLevelHeader inside a restructured wrapper when we don't
// have a live weak_ref for it (e.g. after re-init).
Controls::Grid FindFirstGridDescendantNamed(DependencyObject root,
                                            PCWSTR name) {
    if (!root) {
        return nullptr;
    }
    std::vector<DependencyObject> stack;
    stack.push_back(root);
    while (!stack.empty()) {
        auto current = stack.back();
        stack.pop_back();
        if (auto fe = current.try_as<FrameworkElement>()) {
            if (fe.Name() == name) {
                if (auto grid = fe.try_as<Controls::Grid>()) {
                    return grid;
                }
            }
        }
        int n = Media::VisualTreeHelper::GetChildrenCount(current);
        for (int i = 0; i < n; i++) {
            stack.push_back(Media::VisualTreeHelper::GetChild(current, i));
        }
    }
    return nullptr;
}

// Copy the column/row definitions from the original Grid#TopLevelHeader to the
// new content Grid so that each moved child's Grid.Row/Grid.Column/
// Grid.ColumnSpan attached properties still resolve to the same logical layout
// slot. Width is intentionally not set: the new ScrollViewer has
// HorizontalScrollMode=Disabled, so its ScrollContentPresenter measures content
// against its own viewport - meaning the content Grid stretches to the
// ScrollViewer's actual width (which in turn is whatever yaml chose, e.g. via
// Grid.Column placement in a star-sized wrapper). Forcing a width derived from
// the original TopLevelHeader would tie the pinned content to the apps column's
// width when both live inside the new column-split wrapper, breaking the
// layout.
void ConfigurePinnedContentFromSource(Controls::Grid target,
                                      Controls::Grid source) {
    target.ColumnDefinitions().Clear();
    for (auto const& def : source.ColumnDefinitions()) {
        Controls::ColumnDefinition newDef;
        newDef.Width(def.Width());
        newDef.MinWidth(def.MinWidth());
        newDef.MaxWidth(def.MaxWidth());
        target.ColumnDefinitions().Append(newDef);
    }

    target.RowDefinitions().Clear();
    for (auto const& def : source.RowDefinitions()) {
        Controls::RowDefinition newDef;
        newDef.Height(def.Height());
        newDef.MinHeight(def.MinHeight());
        newDef.MaxHeight(def.MaxHeight());
        target.RowDefinitions().Append(newDef);
    }
}

// Undo `EnsureSeparatePinnedScrollViewer` for a single Border:
// 1. Move each child back from SideBySidePinnedContent into TopLevelHeader.
// 2. Detach the original ScrollViewer from the wrapper and reset Border.Child
//    to it, releasing the wrapper for GC.
//
// Best-effort: silently skips parts that have already been disposed.
void RevertSeparatePinnedScrollForBorder(Controls::Border border,
                                         Controls::Grid sourceTopLevelHeader) {
    if (!border) {
        return;
    }

    auto wrapper = border.Child().try_as<Controls::Grid>();
    if (!wrapper || wrapper.Name() != kSeparatePinnedWrapperName) {
        return;
    }

    UIElement originalScrollViewer{nullptr};
    Controls::Grid contentGrid{nullptr};
    for (uint32_t i = 0; i < wrapper.Children().Size(); i++) {
        auto child = wrapper.Children().GetAt(i);
        auto sv = child.try_as<Controls::ScrollViewer>();
        if (sv && sv.Name() == kSeparatePinnedScrollName) {
            contentGrid = sv.Content().try_as<Controls::Grid>();
        } else if (!originalScrollViewer) {
            originalScrollViewer = child.try_as<UIElement>();
        }
    }

    // If we lost the source ref (e.g. after a re-init), try to (re)find it
    // by walking the original ScrollViewer's subtree.
    if (!sourceTopLevelHeader && originalScrollViewer) {
        sourceTopLevelHeader = FindFirstGridDescendantNamed(
            originalScrollViewer.as<DependencyObject>(), L"TopLevelHeader");
    }

    if (sourceTopLevelHeader && contentGrid) {
        while (contentGrid.Children().Size() > 0) {
            auto child = contentGrid.Children().GetAt(0).try_as<UIElement>();
            contentGrid.Children().RemoveAt(0);
            if (child) {
                sourceTopLevelHeader.Children().Append(child);
            }
        }
    }

    if (originalScrollViewer) {
        uint32_t idx = 0;
        if (wrapper.Children().IndexOf(originalScrollViewer, idx)) {
            wrapper.Children().RemoveAt(idx);
        }
        border.Child(nullptr);
        border.Child(originalScrollViewer);

        // Note: the HorizontalScrollMode / HorizontalScrollBarVisibility that
        // EnsureSeparatePinnedScrollViewer forced to Disabled on the original
        // apps ScrollViewer are intentionally not restored here. The apps list
        // never scrolls horizontally, so the values match the effective default
        // anyway, and we don't capture the pre-override values to restore them.
        // A toggle-off only happens when the override matches the Windows
        // default (no process restart); otherwise the process restarts and the
        // ScrollViewer is recreated fresh.
    }
}

// Walk every tracked entry and revert the tree mutation. Called when the
// user toggles the setting off at runtime and on RestorerSkin_Uninit.
void RevertAllSeparatePinnedScroll() {
    for (auto const& entry : g_separatePinnedScrollEntries) {
        try {
            RevertSeparatePinnedScrollForBorder(
                entry.border.get(), entry.sourceTopLevelHeader.get());
        } catch (winrt::hresult_error const& ex) {
            Wh_Log(L"Error reverting separate pinned scroll %08X: %s",
                   ex.code(), ex.message().c_str());
        }
    }
    g_separatePinnedScrollEntries.clear();
}

// Wrap the inner ScrollViewer in a sibling-capable Grid the first time we see
// the AllAppsGrid's Border, and create the new ScrollViewer + content Grid
// for the moved elements. Idempotent: returns the existing content Grid if
// the Border has already been restructured. `*outCreated` is set to true on
// the call that performs the wrapping (so the caller can do one-time
// configuration like copying layout definitions from the source Grid).
Controls::Grid EnsureSeparatePinnedScrollViewer(Controls::Border border,
                                                bool* outCreated) {
    if (outCreated) {
        *outCreated = false;
    }

    auto currentChild = border.Child();
    if (!currentChild) {
        return nullptr;
    }

    if (auto wrapper = currentChild.try_as<Controls::Grid>()) {
        if (wrapper.Name() == kSeparatePinnedWrapperName) {
            for (uint32_t i = 0; i < wrapper.Children().Size(); i++) {
                auto sv = wrapper.Children()
                              .GetAt(i)
                              .try_as<Controls::ScrollViewer>();
                if (sv && sv.Name() == kSeparatePinnedScrollName) {
                    return sv.Content().try_as<Controls::Grid>();
                }
            }
            return nullptr;
        }
    }

    auto originalScrollViewer = currentChild.try_as<FrameworkElement>();
    if (!originalScrollViewer) {
        return nullptr;
    }

    Wh_Log(L"Restructuring AllAppsGrid Border for separate pinned scroll");

    // Apply the same horizontal-no-scroll configuration to the original apps
    // ScrollViewer that we use for the new pinned ScrollViewer below. Without
    // this, once the apps ScrollViewer is placed inside a star-sized column
    // of the wrapper Grid, its ScrollContentPresenter measures content with
    // infinity width and the inner ItemsPresenter / ItemsWrapGrid grows
    // unbounded instead of fitting the column.
    if (auto originalSv =
            originalScrollViewer.try_as<Controls::ScrollViewer>()) {
        originalSv.HorizontalScrollMode(Controls::ScrollMode::Disabled);
        originalSv.HorizontalScrollBarVisibility(
            Controls::ScrollBarVisibility::Disabled);
    }

    Controls::ScrollViewer newScroll;
    newScroll.Name(kSeparatePinnedScrollName);
    newScroll.VerticalScrollMode(Controls::ScrollMode::Enabled);
    newScroll.VerticalScrollBarVisibility(Controls::ScrollBarVisibility::Auto);
    // Use ScrollBarVisibility::Disabled (not Hidden) for the horizontal axis
    // so the ScrollContentPresenter's CanHorizontallyScroll evaluates to
    // false and the content is measured against the ScrollViewer's viewport
    // width instead of with infinity. Without this, a content Grid with
    // star-sized column definitions cannot resolve its column widths and
    // either collapses or grows unbounded.
    newScroll.HorizontalScrollMode(Controls::ScrollMode::Disabled);
    newScroll.HorizontalScrollBarVisibility(
        Controls::ScrollBarVisibility::Disabled);
    newScroll.Background(nullptr);

    Controls::Grid contentGrid;
    contentGrid.Name(kSeparatePinnedContentName);
    newScroll.Content(contentGrid);

    Controls::Grid wrapper;
    wrapper.Name(kSeparatePinnedWrapperName);

    // Default layout: pinned ScrollViewer pinned to the left at 540px wide,
    // apps ScrollViewer filling the remaining width on the right.
    auto cols = wrapper.ColumnDefinitions();
    Controls::ColumnDefinition pinnedCol;
    pinnedCol.Width(GridLength{540, GridUnitType::Pixel});
    cols.Append(pinnedCol);
    Controls::ColumnDefinition appsCol;
    appsCol.Width(GridLength{1, GridUnitType::Star});
    cols.Append(appsCol);

    Controls::Grid::SetColumn(newScroll, 0);
    Controls::Grid::SetColumn(originalScrollViewer, 1);

    border.Child(nullptr);
    wrapper.Children().Append(originalScrollViewer);
    wrapper.Children().Append(newScroll);
    border.Child(wrapper);

    if (outCreated) {
        *outCreated = true;
    }
    return contentGrid;
}

// Reparent `element` from its current Panel parent to `target`. No-op if it
// is already there or if the current parent is not a Panel (e.g. a
// ContentControl/ContentPresenter, which shouldn't happen for any of the
// four target elements since they are direct children of Grid#TopLevelHeader).
void MoveElementToPinnedContent(FrameworkElement element,
                                Controls::Grid target) {
    auto currentParent = Media::VisualTreeHelper::GetParent(element);
    if (!currentParent) {
        return;
    }

    if (currentParent == target.as<DependencyObject>()) {
        return;
    }

    auto parentPanel = currentParent.try_as<Controls::Panel>();
    if (!parentPanel) {
        Wh_Log(L"SeparatePinnedScroll: parent of %s is not a Panel, skipping",
               element.Name().c_str());
        return;
    }

    auto uiElement = element.try_as<UIElement>();
    if (!uiElement) {
        return;
    }

    uint32_t index = 0;
    if (!parentPanel.Children().IndexOf(uiElement, index)) {
        Wh_Log(L"SeparatePinnedScroll: %s not found in its parent's children",
               element.Name().c_str());
        return;
    }

    parentPanel.Children().RemoveAt(index);
    target.Children().Append(uiElement);
}

void HandleSeparatePinnedScroll(FrameworkElement element) {
    // >>> win10-skin: only StartMenu has pinned items scroll <<<
    if (g_target != Target::StartMenu) {
        return;
    }
    // <<< win10-skin: only StartMenu has pinned items scroll <<<
    if (g_disableNewStartMenuLayout !=
        DisableNewStartMenuLayout::newLayoutSideBySide) {
        return;
    }

    if (!IsSeparatePinnedScrollTargetName(element.Name())) {
        return;
    }

    // Defer to the next dispatcher tick so we don't mutate the visual tree
    // while the tree watcher is still delivering the Add event for `element`.
    auto action = element.Dispatcher().TryRunAsync(
        winrt::Windows::UI::Core::CoreDispatcherPriority::Normal,
        [weakElement = winrt::make_weak(element)]() {
            auto element = weakElement.get();
            if (!element) {
                return;
            }

            try {
                FrameworkElement allAppsGrid{nullptr};
                Controls::Grid topLevelHeader{nullptr};
                DependencyObject iter = element;
                while (auto parent = Media::VisualTreeHelper::GetParent(iter)) {
                    iter = parent;
                    auto fe = iter.try_as<FrameworkElement>();
                    if (!fe) {
                        continue;
                    }
                    if (!topLevelHeader && fe.Name() == L"TopLevelHeader") {
                        topLevelHeader = fe.try_as<Controls::Grid>();
                    }
                    if (fe.Name() == L"AllAppsGrid" &&
                        winrt::get_class_name(fe) ==
                            L"Windows.UI.Xaml.Controls.GridView") {
                        allAppsGrid = fe;
                        break;
                    }
                }
                if (!allAppsGrid) {
                    return;
                }

                if (Media::VisualTreeHelper::GetChildrenCount(allAppsGrid) ==
                    0) {
                    return;
                }
                auto firstChild =
                    Media::VisualTreeHelper::GetChild(allAppsGrid, 0);
                auto border = firstChild.try_as<Controls::Border>();
                if (!border) {
                    return;
                }

                bool created = false;
                auto contentGrid =
                    EnsureSeparatePinnedScrollViewer(border, &created);
                if (!contentGrid) {
                    return;
                }

                if (created && topLevelHeader) {
                    ConfigurePinnedContentFromSource(contentGrid,
                                                     topLevelHeader);
                    // Prune entries whose Border has been destroyed (e.g.
                    // Start menu instances opened in previous sessions of
                    // the host process) before pushing the new one.
                    std::erase_if(g_separatePinnedScrollEntries,
                                  [](SeparatePinnedScrollEntry const& e) {
                                      return !e.border.get();
                                  });
                    g_separatePinnedScrollEntries.push_back(
                        {winrt::make_weak(border),
                         winrt::make_weak(topLevelHeader)});
                }

                MoveElementToPinnedContent(element, contentGrid);
            } catch (winrt::hresult_error const& ex) {
                Wh_Log(L"SeparatePinnedScroll error %08X: %s", ex.code(),
                       ex.message().c_str());
            }
        });

    // Track the pending callback so UninitializeSettingsAndTap can cancel it on
    // teardown. Prune already-finished actions first to keep the list bounded
    // (at most a handful are ever in flight - one per target element per Start
    // menu instance).
    std::erase_if(
        g_separatePinnedScrollPendingActions,
        [](winrt::Windows::Foundation::IAsyncOperation<bool> const& a) {
            return !a || a.Status() !=
                             winrt::Windows::Foundation::AsyncStatus::Started;
        });
    if (action) {
        g_separatePinnedScrollPendingActions.push_back(std::move(action));
    }
}

void ApplyCustomizations(InstanceHandle handle,
                         FrameworkElement element,
                         PCWSTR fallbackClassName) {
    // Merge resource dictionary on first element add. Merging it earlier on
    // window creation doesn't work, perhaps merged dictionaries are reset
    // during initialization.
    if (!g_resourceVariablesThemeDict) {
        MergeResourceVariables();
    }

    HandleSeparatePinnedScroll(element);
    ActionCenterSkin::Observe(handle, element);  // New rules/insertion never target jump lists.

    if (!g_webContentCss.empty() || !g_webContentJs.empty()) {
        try {
            ApplyCustomizationsIfWebView(handle, element);
        } catch (winrt::hresult_error const& ex) {
            Wh_Log(L"Error %08X: %s", ex.code(), ex.message().c_str());
        }
    }

    auto* state = GetStyleVariableState();
    if (!state) {
        RESTORER_VERBOSE_LOG(L"No XamlRoot for %s, skipping",
               winrt::get_class_name(element).c_str());
        return;
    }

    // >>> win10-skin: start menu position <<<
    StartMenuPosition::OnElementAdded(element);
    // <<< win10-skin: start menu position <<<

    auto resolved = FindElementPropertyOverrides(element, fallbackClassName);
    if (resolved.overridesPerVSG.empty() && resolved.captures.empty()) {
        return;
    }

    RESTORER_VERBOSE_LOG(L"Applying styles to %s", winrt::get_class_name(element).c_str());

    auto& elementCustomizationState = g_elementsCustomizationState[handle];

    for (const auto& [visualStateGroupOptionalWeakPtrIter, stateIter] :
         elementCustomizationState.perVisualStateGroup) {
        RestoreCustomizationsForVisualStateGroup(
            state, handle, element, visualStateGroupOptionalWeakPtrIter,
            stateIter);
    }

    elementCustomizationState.element = element;
    elementCustomizationState.perVisualStateGroup.clear();

    // Elements that neither capture nor consume a variable pay nothing. The
    // rest get their spine now that the element has been matched; if it isn't
    // attached yet the walk yields nothing and EnsureElementTreeNode retries on
    // first use. Cleared unconditionally so a re-apply that drops all variable
    // use cannot leave a stale node behind.
    elementCustomizationState.treeNode = nullptr;
    if (!resolved.captures.empty() || resolved.hasDynamicValues) {
        elementCustomizationState.treeNode =
            GetOrCreateElementTreeNode(element);
    }

    // Wire up captures first so any variables they define are visible to
    // dynamic value-rules applied below. Note: SetUpCapturesForElement does not
    // need this element's fallbackClassName -- propagation routes through each
    // consumer's own stored fallback.
    SetUpCapturesForElement(state, handle, element, resolved.captures,
                            &elementCustomizationState);

    for (auto& [visualStateGroup, overridesForVisualStateGroup] :
         resolved.overridesPerVSG) {
        std::optional<winrt::weak_ref<VisualStateGroup>>
            visualStateGroupOptionalWeakPtr;
        if (visualStateGroup) {
            visualStateGroupOptionalWeakPtr = visualStateGroup;
        }

        elementCustomizationState.perVisualStateGroup.push_back(
            {visualStateGroupOptionalWeakPtr, {}});
        auto* elementCustomizationStateForVisualStateGroup =
            &elementCustomizationState.perVisualStateGroup.back().second;

        ApplyCustomizationsForVisualStateGroup(
            state, handle, element, visualStateGroup, fallbackClassName,
            std::move(overridesForVisualStateGroup),
            elementCustomizationStateForVisualStateGroup);
    }

    // >>> win10-skin: start menu position <<<
    StartMenuPosition::OnElementStyled(element);
    // <<< win10-skin: start menu position <<<
}

void CleanupCustomizations(InstanceHandle handle) {
    ActionCenterSkin::Removed(handle);  // Marks our own region only; no tree mutation here.
    if (auto it = g_elementsCustomizationState.find(handle);
        it != g_elementsCustomizationState.end()) {
        // A reference rather than the iterator: restoring a style below runs
        // arbitrary XAML work that can re-enter ApplyCustomizations and rehash
        // g_elementsCustomizationState, which invalidates iterators but not
        // references to the mapped values.
        auto& elementCustomizationState = it->second;

        auto element = elementCustomizationState.element.get();
        auto* state = GetStyleVariableState();

        RestoreCapturesForElement(element, elementCustomizationState);

        // Drop this element's captures from the registry. Other elements may
        // still capture the same names, so a name only becomes undefined once
        // its last capture is gone. Runs after RestoreCapturesForElement so the
        // just-unregistered capture callbacks can't re-seed a variable
        // mid-teardown.
        std::vector<std::wstring> removedVarNames;
        if (state) {
            for (const auto& [property, captureState] :
                 elementCustomizationState.captureCustomizationStates) {
                if (captureState.varName.empty()) {
                    continue;
                }

                auto varIt = state->variables.find(captureState.varName);
                if (varIt == state->variables.end()) {
                    continue;
                }

                if (!std::erase_if(
                        varIt->second,
                        [handle](const StyleVariableCapture& capture) {
                            return capture.elementHandle == handle;
                        })) {
                    continue;
                }

                removedVarNames.push_back(captureState.varName);
                if (varIt->second.empty()) {
                    state->variables.erase(varIt);
                }
            }
        }

        for (const auto& [visualStateGroupOptionalWeakPtrIter, stateIter] :
             elementCustomizationState.perVisualStateGroup) {
            RestoreCustomizationsForVisualStateGroup(
                state, handle, element, visualStateGroupOptionalWeakPtrIter,
                stateIter);
        }

        // By handle, not by `it`: a re-entrant apply above may have rehashed
        // the map since the lookup.
        g_elementsCustomizationState.erase(handle);

        ReapElementTreeNodesIfNeeded();

        // Deferred until this element is out of g_elementsCustomizationState,
        // both so it can't be scored as a winning capture while being torn down
        // and so the loops above don't walk state that re-entrant style applies
        // could invalidate. Every removal propagates, not just the one that
        // left a name undefined: dropping one of several captures still changes
        // which one wins for the consumers that were closest to it.
        for (const auto& varName : removedVarNames) {
            PropagateStyleVariableChange(state, varName, std::nullopt);
        }
    }

    if (auto it = g_webViewsCustomizationState.find(handle);
        it != g_webViewsCustomizationState.end()) {
        const auto& webViewCustomizationState = it->second;
        try {
            ClearWebViewCustomizations(webViewCustomizationState);
        } catch (winrt::hresult_error const& ex) {
            Wh_Log(L"Error %08X: %s", ex.code(), ex.message().c_str());
        }

        g_webViewsCustomizationState.erase(it);
    }
}

using StyleConstant = std::pair<std::wstring, std::wstring>;
using StyleConstants = std::vector<StyleConstant>;

std::wstring ApplyStyleConstants(std::wstring_view style,
                                 const StyleConstants& styleConstants) {
    std::wstring result;

    size_t lastPos = 0;
    size_t findPos;

    while ((findPos = style.find('$', lastPos)) != style.npos) {
        result.append(style, lastPos, findPos - lastPos);

        const StyleConstant* constant = nullptr;
        for (const auto& s : styleConstants) {
            if (s.first == style.substr(findPos + 1, s.first.size())) {
                constant = &s;
                break;
            }
        }

        if (constant) {
            result += constant->second;
            lastPos = findPos + 1 + constant->first.size();
        } else {
            result += '$';
            lastPos = findPos + 1;
        }
    }

    // Care for the rest after last occurrence.
    result += style.substr(lastPos);

    return result;
}

std::optional<StyleConstant> ParseStyleConstant(
    std::wstring_view constant,
    const StyleConstants& styleConstants) {
    // Skip if commented.
    if (constant.starts_with(L"//")) {
        return std::nullopt;
    }

    auto eqPos = constant.find(L'=');
    if (eqPos == constant.npos) {
        Wh_Log(L"Skipping entry with no '=': %.*s",
               static_cast<int>(constant.length()), constant.data());
        return std::nullopt;
    }

    auto key = TrimStringView(constant.substr(0, eqPos));
    auto valueRaw = TrimStringView(constant.substr(eqPos + 1));
    auto value = ApplyStyleConstants(valueRaw, styleConstants);

    return StyleConstant{std::wstring(key), std::move(value)};
}

StyleConstants LoadStyleConstants(
    const std::vector<PCWSTR>& themeStyleConstants) {
    StyleConstants result;

    auto addToResult = [&result](StyleConstant sc) {
        // Keep sorted by name length to replace long names first. Reverse the
        // order to allow overriding definitions with the same name.
        auto insertIndex = std::lower_bound(
            result.begin(), result.end(), sc,
            [](const StyleConstant& a, const StyleConstant& b) {
                return a.first.size() > b.first.size();
            });

        result.insert(insertIndex, std::move(sc));
    };

    // >>> win10-skin: localized search placeholder <<<
    addToResult(StyleConstant{
        L"SearchPlaceholderText",
        StartMenuPosition::GetLocalizedSearchPlaceholder()});
    // <<< win10-skin: localized search placeholder <<<

    for (const auto themeStyleConstant : themeStyleConstants) {
        if (auto parsed = ParseStyleConstant(themeStyleConstant, result)) {
            addToResult(std::move(*parsed));
        }
    }

    for (int i = 0;; i++) {
        string_setting_unique_ptr constantSetting(
            Wh_GetStringSetting(L"styleConstants[%d]", i));
        if (!*constantSetting.get()) {
            break;
        }

        if (auto parsed = ParseStyleConstant(constantSetting.get(), result)) {
            addToResult(std::move(*parsed));
        }
    }

    return result;
}

ElementMatcher ElementMatcherFromString(std::wstring_view str) {
    ElementMatcher result;
    PropertyValuesUnresolved propertyValuesUnresolved;

    auto trimmed = TrimStringView(str);
    if (trimmed == L"*") {
        result.kind = ElementMatcher::Kind::Wildcard;
        return result;
    }
    if (trimmed == L":root") {
        result.kind = ElementMatcher::Kind::Root;
        return result;
    }

    auto i = str.find_first_of(L"#@[");
    result.type = TrimStringView(str.substr(0, i));
    if (result.type.empty()) {
        throw std::runtime_error("Bad target syntax, empty type");
    }

    while (i != str.npos) {
        auto iNext = str.find_first_of(L"#@[", i + 1);
        auto nextPart =
            str.substr(i + 1, iNext == str.npos ? str.npos : iNext - (i + 1));

        switch (str[i]) {
            case L'#':
                if (!result.name.empty()) {
                    throw std::runtime_error(
                        "Bad target syntax, more than one name");
                }

                result.name = TrimStringView(nextPart);
                if (result.name.empty()) {
                    throw std::runtime_error("Bad target syntax, empty name");
                }
                break;

            case L'@':
                if (result.visualStateGroupName) {
                    throw std::runtime_error(
                        "Bad target syntax, more than one visual state group");
                }

                result.visualStateGroupName = TrimStringView(nextPart);
                break;

            case L'[': {
                auto rule = TrimStringView(nextPart);
                if (rule.length() == 0 || rule.back() != L']') {
                    throw std::runtime_error("Bad target syntax, missing ']'");
                }

                rule = TrimStringView(rule.substr(0, rule.length() - 1));
                if (rule.length() == 0) {
                    throw std::runtime_error(
                        "Bad target syntax, empty property");
                }

                if (rule.find_first_not_of(L"0123456789") == rule.npos) {
                    result.oneBasedIndex = std::stoi(std::wstring(rule));
                    break;
                }

                auto ruleEqPos = rule.find(L'=');
                if (ruleEqPos == rule.npos) {
                    throw std::runtime_error(
                        "Bad target syntax, missing '=' in property");
                }

                auto ruleKey = TrimStringView(rule.substr(0, ruleEqPos));
                auto ruleVal = TrimStringView(rule.substr(ruleEqPos + 1));

                if (ruleKey.length() == 0) {
                    throw std::runtime_error(
                        "Bad target syntax, empty property name");
                }

                propertyValuesUnresolved.push_back(
                    {std::wstring(ruleKey), std::wstring(ruleVal)});
                break;
            }

            default:
                throw std::runtime_error("Bad target syntax");
        }

        i = iNext;
    }

    result.propertyValues = std::move(propertyValuesUnresolved);

    return result;
}

// Parses a single `controlStyles[*].styles[*]` entry into either a ValueRule
// (`Property[@VisualState][:]=value`) or a CaptureRule (`Property=>VarName`).
// Throws std::runtime_error on malformed input or disallowed combinations such
// as `:=>` or `@VisualState=>`.
std::variant<ValueRule, CaptureRule> ParseRule(std::wstring_view str) {
    auto eqPos = str.find(L'=');
    if (eqPos == str.npos) {
        throw std::runtime_error("Bad style syntax, '=' is missing");
    }

    auto name = str.substr(0, eqPos);
    auto value = str.substr(eqPos + 1);

    if (!value.empty() && value.front() == L'>') {
        // Capture rule: `Property=>VarName`. The right-hand side (after the
        // leading `>` marker) is the name of a mod-global style variable into
        // which the property's current value is captured.
        value = value.substr(1);

        if (!name.empty() && name.back() == L':') {
            throw std::runtime_error(
                "Bad style syntax, ':=>' is not valid (':=' XAML value "
                "cannot be combined with '=>' capture)");
        }

        if (name.find(L'@') != name.npos) {
            throw std::runtime_error(
                "Bad style syntax, '@VisualState' not allowed on a capture "
                "rule");
        }

        auto trimmedPropertyName = TrimStringView(name);
        if (trimmedPropertyName.empty()) {
            throw std::runtime_error("Bad style syntax, empty name");
        }

        auto trimmedVarName = TrimStringView(value);
        if (trimmedVarName.empty()) {
            throw std::runtime_error(
                "Bad style syntax, empty capture variable name");
        }
        if (!IsValidStyleVariableIdentifier(trimmedVarName)) {
            throw std::runtime_error(
                "Bad style syntax, invalid capture variable name");
        }

        return CaptureRule{std::wstring(trimmedPropertyName),
                           std::wstring(trimmedVarName)};
    }

    ValueRule result;
    result.value = TrimStringView(value);

    if (!name.empty() && name.back() == L':') {
        result.isXamlValue = true;
        name = name.substr(0, name.size() - 1);
    }

    auto atPos = name.find(L'@');
    if (atPos != name.npos) {
        result.visualState = TrimStringView(name.substr(atPos + 1));
        name = name.substr(0, atPos);
    }

    result.propertyName = TrimStringView(name);
    if (result.propertyName.empty()) {
        throw std::runtime_error("Bad style syntax, empty name");
    }

    return result;
}

std::wstring AdjustTypeName(std::wstring_view type) {
    if (type.find_first_of(L".:") == type.npos) {
        if (type == L"Rectangle") {
            return L"Windows.UI.Xaml.Shapes.Rectangle";
        }

        return L"Windows.UI.Xaml.Controls." + std::wstring{type};
    }

    static const std::vector<std::pair<std::wstring_view, std::wstring_view>>
        adjustments = {
            {L"StartMenu:", L"StartMenu."},
            {L"muxc:", L"Microsoft.UI.Xaml.Controls."},
        };

    for (const auto& adjustment : adjustments) {
        if (type.starts_with(adjustment.first)) {
            auto result = std::wstring{adjustment.second};
            result += type.substr(adjustment.first.size());
            return result;
        }
    }

    return std::wstring{type};
}

// Splits a target string on the commas which separate targets, ignoring commas
// which are part of a `[Property=Value]` clause.
std::vector<std::wstring_view> SplitTargetString(std::wstring_view target) {
    std::vector<std::wstring_view> result;

    size_t partBegin = 0;
    bool inProperty = false;
    for (size_t i = 0; i < target.size(); i++) {
        switch (target[i]) {
            case L'[':
                inProperty = true;
                break;

            case L']':
                inProperty = false;
                break;

            case L',':
                if (!inProperty) {
                    result.push_back(target.substr(partBegin, i - partBegin));
                    partBegin = i + 1;
                }
                break;
        }
    }

    result.push_back(target.substr(partBegin));

    return result;
}

void AddElementCustomizationRulesForSingleTarget(
    std::wstring_view target,
    const std::vector<std::wstring>& styles) {
    ElementCustomizationRules elementCustomizationRules;

    auto targetParts = SplitStringView(target, L" > ");

    bool first = true;
    bool hasVisualStateGroup = false;
    for (auto i = targetParts.rbegin(); i != targetParts.rend(); ++i) {
        const auto& targetPart = *i;
        const bool isLeftmost = (i + 1 == targetParts.rend());

        auto matcher = ElementMatcherFromString(targetPart);

        const auto& prevParents =
            elementCustomizationRules.parentElementMatchers;
        const bool prevIsWildcard =
            !prevParents.empty() &&
            prevParents.back().kind == ElementMatcher::Kind::Wildcard;

        switch (matcher.kind) {
            case ElementMatcher::Kind::Element:
                matcher.type = AdjustTypeName(matcher.type);
                break;

            case ElementMatcher::Kind::Wildcard:
                if (first) {
                    throw std::runtime_error(
                        "Bad target syntax, '*' can't be the matched element");
                }
                if (isLeftmost) {
                    throw std::runtime_error(
                        "Bad target syntax, '*' can't be the leftmost target "
                        "part");
                }
                if (prevIsWildcard) {
                    throw std::runtime_error(
                        "Bad target syntax, '*' can't be adjacent to another "
                        "'*'");
                }
                break;

            case ElementMatcher::Kind::Root:
                if (first) {
                    throw std::runtime_error(
                        "Bad target syntax, ':root' can't be the matched "
                        "element");
                }
                if (!isLeftmost) {
                    throw std::runtime_error(
                        "Bad target syntax, ':root' must be the leftmost "
                        "target part");
                }
                if (prevIsWildcard) {
                    throw std::runtime_error(
                        "Bad target syntax, ':root' must be followed by a "
                        "non-wildcard target part");
                }
                break;
        }

        if (matcher.visualStateGroupName) {
            if (hasVisualStateGroup) {
                throw std::runtime_error(
                    "Element type can't have more than one visual state group");
            }

            hasVisualStateGroup = true;
        }

        if (first) {
            UnresolvedRules unresolvedRules;
            for (const auto& style : styles) {
                auto parsed = ParseRule(style);
                if (auto* valueRule = std::get_if<ValueRule>(&parsed)) {
                    unresolvedRules.valueRules.push_back(std::move(*valueRule));
                } else {
                    unresolvedRules.captureRules.push_back(
                        std::move(std::get<CaptureRule>(parsed)));
                }
            }

            elementCustomizationRules.elementMatcher = std::move(matcher);
            elementCustomizationRules.propertyOverrides =
                std::move(unresolvedRules);
        } else {
            elementCustomizationRules.parentElementMatchers.push_back(
                std::move(matcher));
        }

        first = false;
    }

    g_elementsCustomizationRules.push_back(
        std::move(elementCustomizationRules));
}

void AddElementCustomizationRules(std::wstring_view target,
                                  const std::vector<std::wstring>& styles) {
    auto targets = SplitTargetString(target);

    for (const auto& singleTarget : targets) {
        try {
            AddElementCustomizationRulesForSingleTarget(singleTarget, styles);
        } catch (winrt::hresult_error const& ex) {
            Wh_Log(L"Error %08X for target %.*s", ex.code(),
                   static_cast<int>(singleTarget.length()),
                   singleTarget.data());
        } catch (std::exception const& ex) {
            Wh_Log(L"Error for target %.*s: %S",
                   static_cast<int>(singleTarget.length()), singleTarget.data(),
                   ex.what());
        }
    }
}

bool ProcessSingleTargetStylesFromSettings(
    int index,
    const StyleConstants& styleConstants) {
    string_setting_unique_ptr targetStringSetting(
        Wh_GetStringSetting(L"controlStyles[%d].target", index));
    if (!*targetStringSetting.get()) {
        return false;
    }

    // Skip if commented.
    if (targetStringSetting[0] == L'/' && targetStringSetting[1] == L'/') {
        return true;
    }

    Wh_Log(L"Processing styles for %s", targetStringSetting.get());

    std::vector<std::wstring> styles;

    for (int styleIndex = 0;; styleIndex++) {
        string_setting_unique_ptr styleSetting(Wh_GetStringSetting(
            L"controlStyles[%d].styles[%d]", index, styleIndex));
        if (!*styleSetting.get()) {
            break;
        }

        // Skip if commented.
        if (styleSetting[0] == L'/' && styleSetting[1] == L'/') {
            continue;
        }

        styles.push_back(
            ApplyStyleConstants(styleSetting.get(), styleConstants));
    }

    if (styles.size() > 0) {
        AddElementCustomizationRules(targetStringSetting.get(), styles);
    }

    return true;
}

void ProcessWebStylesFromSettings(
    const StyleConstants& styleConstants,
    const std::vector<ThemeTargetStyles>& themeStyles) {
    std::wstring webContentCss;

    for (const auto& themeStyle : themeStyles) {
        Wh_Log(L"Processing theme WebView styles for %s", themeStyle.target);

        webContentCss += themeStyle.target;
        webContentCss += L" {\n";

        for (const auto& style : themeStyle.styles) {
            webContentCss += ApplyStyleConstants(style, styleConstants);
            webContentCss += L";\n";
        }

        webContentCss += L"}\n";
    }

    for (int i = 0;; i++) {
        string_setting_unique_ptr targetStringSetting(
            Wh_GetStringSetting(L"webContentStyles[%d].target", i));
        if (!*targetStringSetting.get()) {
            break;
        }

        Wh_Log(L"Processing WebView styles for %s", targetStringSetting.get());

        webContentCss += targetStringSetting.get();
        webContentCss += L" {\n";

        for (int styleIndex = 0;; styleIndex++) {
            string_setting_unique_ptr styleSetting(Wh_GetStringSetting(
                L"webContentStyles[%d].styles[%d]", i, styleIndex));
            if (!*styleSetting.get()) {
                break;
            }

            // Skip if commented.
            if (styleSetting[0] == L'/' && styleSetting[1] == L'/') {
                continue;
            }

            webContentCss +=
                ApplyStyleConstants(styleSetting.get(), styleConstants);
            webContentCss += L";\n";
        }

        webContentCss += L"}\n";
    }

    g_webContentCss = std::move(webContentCss);
    g_webContentJs =
        string_setting_unique_ptr(Wh_GetStringSetting(L"webContentCustomJs"))
            .get();
    // >>> win10-skin: webview theme sync <<<
    if (!g_webContentCss.empty()) {
        std::wstring themeSyncJs = LR"(
        try {
            const s = document.getElementById(styleElementId);
            if (s && s.textContent !== styleContent) {
                s.textContent = styleContent;
            }
            if (document.body) {
                document.body.classList.remove("cobalt", "undocked");
                if (styleContent.indexOf("color-scheme: light") !== -1) {
                    document.body.classList.remove("b_dark", "dark");
                    document.body.classList.add("b_light", "light");
                } else if (styleContent.indexOf("color-scheme: dark") !== -1) {
                    document.body.classList.remove("b_light", "light");
                    document.body.classList.add("b_dark", "dark");
                }
            }
            if (window._w && window._w.CortanaApp) {
                const ca = window._w.CortanaApp;
                if (typeof ca === "object") {
                    ca.useCobaltCSS = false;
                    ca.userProfileButtonEnabled = 0;
                    ca.undocked = 0;
                    ca.newQuickAccess = 0;
                    ca.enableTwoPanesZI = 0;
                }
            }
        } catch (e) {}
        )";
        g_webContentJs = themeSyncJs + L"\n" + g_webContentJs;
    }
    // <<< win10-skin: webview theme sync <<<
}

std::optional<ResourceVariableEntry> ParseResourceVariable(
    std::wstring_view entry,
    const StyleConstants& styleConstants) {
    // Skip if commented.
    if (entry.starts_with(L"//")) {
        return std::nullopt;
    }

    // Find the first '=' to split key and value.
    auto eqPos = entry.find(L'=');
    if (eqPos == entry.npos) {
        Wh_Log(L"Skipping entry with no '=': %.*s",
               static_cast<int>(entry.length()), entry.data());
        return std::nullopt;
    }

    auto keyPart = TrimStringView(entry.substr(0, eqPos));
    auto valueRaw = TrimStringView(entry.substr(eqPos + 1));
    auto value = ApplyStyleConstants(valueRaw, styleConstants);

    constexpr std::wstring_view kThemeResourcePrefix = L"{ThemeResource ";

    ResourceVariableType type = ResourceVariableType::String;
    if (keyPart.size() > 0 && keyPart.back() == L':') {
        type = ResourceVariableType::Xaml;
        keyPart = keyPart.substr(0, keyPart.size() - 1);
        keyPart = TrimStringView(keyPart);
    } else if (value.starts_with(kThemeResourcePrefix) &&
               value.ends_with(L"}")) {
        type = ResourceVariableType::ThemeResourceReference;
        value = TrimStringView(
            value.substr(kThemeResourcePrefix.size(),
                         value.size() - kThemeResourcePrefix.size() - 1));
    }

    ResourceVariableTheme theme = ResourceVariableTheme::None;
    std::wstring key;

    // Check for @theme suffix in key part.
    auto atPos = keyPart.find(L'@');
    if (atPos != keyPart.npos) {
        key = TrimStringView(keyPart.substr(0, atPos));
        auto themePart = TrimStringView(keyPart.substr(atPos + 1));
        if (themePart == L"Dark") {
            theme = ResourceVariableTheme::Dark;
        } else if (themePart == L"Light") {
            theme = ResourceVariableTheme::Light;
        } else {
            Wh_Log(L"Unknown theme '%.*s', expected 'Dark' or 'Light'",
                   static_cast<int>(themePart.size()), themePart.data());
            return std::nullopt;
        }
    } else {
        key = std::wstring(keyPart);
    }

    return ResourceVariableEntry{std::move(key), std::move(value), theme, type};
}

winrt::Windows::Foundation::IInspectable ParseXamlValue(
    std::wstring_view xamlValue) {
    std::wstring xaml;
    xaml += L"        <Setter Property=\"Tag\">\n";
    xaml += L"            <Setter.Value>\n";
    xaml += xamlValue;
    xaml += L"\n";
    xaml += L"            </Setter.Value>\n";
    xaml += L"        </Setter>\n";

    auto style = GetStyleFromXamlSetters(L"FrameworkElement", xaml);
    return style.Setters().GetAt(0).as<Setter>().Value();
}

bool ProcessResourceVariable(ResourceDictionary resources,
                             ResourceDictionary darkDict,
                             ResourceDictionary lightDict,
                             const ResourceVariableEntry& entry) {
    auto boxedKey = winrt::box_value(entry.key);

    if (entry.theme != ResourceVariableTheme::None) {
        ResourceDictionary& targetDict =
            entry.theme == ResourceVariableTheme::Dark ? darkDict : lightDict;

        if (targetDict.HasKey(boxedKey)) {
            Wh_Log(
                L"Resource variable key '%s' already exists in theme '%s', "
                L"skipping",
                entry.key.c_str(),
                entry.theme == ResourceVariableTheme::Dark ? L"Dark"
                                                           : L"Light");
            return false;
        }

        winrt::Windows::Foundation::IInspectable value;
        switch (entry.type) {
            case ResourceVariableType::String:
                value = winrt::box_value(entry.value);
                break;
            case ResourceVariableType::Xaml:
                value =
                    entry.value.empty() ? nullptr : ParseXamlValue(entry.value);
                break;
            case ResourceVariableType::ThemeResourceReference:
                value = resources.Lookup(winrt::box_value(entry.value));
                break;
        }

        targetDict.Insert(boxedKey, value);

        return true;
    }

    // key= - convert using existing resource type.
    auto existingResource = resources.TryLookup(boxedKey);
    if (!existingResource) {
        Wh_Log(L"Resource variable key '%s' not found, skipping",
               entry.key.c_str());
        return false;
    }

    auto [it, inserted] =
        g_originalResourceValues.try_emplace(entry.key, existingResource);
    if (!inserted) {
        Wh_Log(L"Resource variable key '%s' already modified, skipping",
               entry.key.c_str());
        return false;
    }

    winrt::Windows::Foundation::IInspectable value;
    switch (entry.type) {
        case ResourceVariableType::String: {
            auto resourceClassName = winrt::get_class_name(existingResource);

            // Unwrap IReference<T> to get inner type name.
            if (resourceClassName.starts_with(
                    L"Windows.Foundation.IReference`1<") &&
                resourceClassName.ends_with(L'>')) {
                size_t prefixSize =
                    sizeof("Windows.Foundation.IReference`1<") - 1;
                resourceClassName =
                    winrt::hstring(resourceClassName.data() + prefixSize,
                                   resourceClassName.size() - prefixSize - 1);
            }

            value = Markup::XamlBindingHelper::ConvertValue(
                Interop::TypeName{resourceClassName},
                winrt::box_value(entry.value));
            break;
        }

        case ResourceVariableType::Xaml:
            value = entry.value.empty() ? nullptr : ParseXamlValue(entry.value);
            break;

        case ResourceVariableType::ThemeResourceReference:
            value = resources.Lookup(winrt::box_value(entry.value));
            break;
    }

    resources.Insert(boxedKey, value);

    return true;
}

void RefreshThemeResourceEntries() {
    if (g_resourceVariables.empty()) {
        return;
    }

    Wh_Log(L"Refreshing theme resource entries");

    auto resources = Application::Current().Resources();

    auto darkDict = g_resourceVariablesThemeDict.ThemeDictionaries()
                        .TryLookup(winrt::box_value(L"Dark"))
                        .try_as<ResourceDictionary>();
    auto lightDict = g_resourceVariablesThemeDict.ThemeDictionaries()
                         .TryLookup(winrt::box_value(L"Light"))
                         .try_as<ResourceDictionary>();

    for (const auto& entry : g_resourceVariables) {
        if (entry.type != ResourceVariableType::ThemeResourceReference) {
            continue;
        }

        try {
            auto boxedKey = winrt::box_value(entry.key);
            auto value = resources.Lookup(winrt::box_value(entry.value));

            if (entry.theme == ResourceVariableTheme::Dark && darkDict) {
                darkDict.Insert(boxedKey, value);
            } else if (entry.theme == ResourceVariableTheme::Light &&
                       lightDict) {
                lightDict.Insert(boxedKey, value);
            } else {
                resources.Insert(boxedKey, value);
            }
        } catch (winrt::hresult_error const& ex) {
            Wh_Log(L"Error refreshing '%s': %08X", entry.key.c_str(),
                   ex.code());
        }
    }
}

std::vector<ResourceVariableEntry> ProcessResourceVariablesFromSettings(
    const StyleConstants& styleConstants,
    const std::vector<PCWSTR>& themeResourceVariables) {
    std::vector<ResourceVariableEntry> resourceVariables;

    for (const auto& themeResourceVariable : themeResourceVariables) {
        Wh_Log(L"Processing theme resource variable %s", themeResourceVariable);

        auto parsed =
            ParseResourceVariable(themeResourceVariable, styleConstants);
        if (parsed) {
            resourceVariables.push_back(std::move(*parsed));
        }
    }

    for (int i = 0;; i++) {
        string_setting_unique_ptr setting(
            Wh_GetStringSetting(L"themeResourceVariables[%d]", i));
        if (!*setting.get()) {
            break;
        }

        Wh_Log(L"Processing resource variable %s", setting.get());

        auto parsed = ParseResourceVariable(setting.get(), styleConstants);
        if (parsed) {
            resourceVariables.push_back(std::move(*parsed));
        }
    }

    return resourceVariables;
}

void MergeResourceVariables() {
    auto resources = Application::Current().Resources();

    // Create theme dictionaries for @Dark/@Light resources.
    g_resourceVariablesThemeDict = ResourceDictionary();
    ResourceDictionary darkDict;
    ResourceDictionary lightDict;
    bool hasThemeResources = false;
    bool hasThemeResourceReferences = false;

    for (auto it = g_resourceVariables.rbegin();
         it != g_resourceVariables.rend(); ++it) {
        Wh_Log(L"Processing resource variable %s", it->key.c_str());

        try {
            if (ProcessResourceVariable(resources, darkDict, lightDict, *it)) {
                if (it->theme != ResourceVariableTheme::None) {
                    hasThemeResources = true;
                }

                if (it->type == ResourceVariableType::ThemeResourceReference) {
                    hasThemeResourceReferences = true;
                }
            }
        } catch (winrt::hresult_error const& ex) {
            Wh_Log(L"Error %08X: %s", ex.code(), ex.message().c_str());
        } catch (std::exception const& ex) {
            Wh_Log(L"Error: %S", ex.what());
        }
    }

    if (hasThemeResources) {
        g_resourceVariablesThemeDict.ThemeDictionaries().Insert(
            winrt::box_value(L"Dark"), darkDict);
        g_resourceVariablesThemeDict.ThemeDictionaries().Insert(
            winrt::box_value(L"Light"), lightDict);

        resources.MergedDictionaries().Append(g_resourceVariablesThemeDict);
    }

    // Register for color changes to refresh theme resource references.
    if (hasThemeResourceReferences) {
        g_uiSettings = winrt::Windows::UI::ViewManagement::UISettings();
        auto dispatcherQueue =
            winrt::Windows::System::DispatcherQueue::GetForCurrentThread();
        g_colorValuesChangedToken =
            g_uiSettings.ColorValuesChanged([dispatcherQueue](auto&&, auto&&) {
                dispatcherQueue.TryEnqueue(RefreshThemeResourceEntries);
            });
    }
}

// >>> win10-skin: colour scheme <<<
// Which shell/app theme is Windows using? 1 = light, 0 = dark.
// Reads SystemUsesLightTheme first (the Windows shell theme used by the
// taskbar, Start menu and SearchHost) and falls back to AppsUseLightTheme.
bool IsSystemLightTheme() {
    DWORD value = 0;
    DWORD size = sizeof(value);
    HKEY key = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER,
                      L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\"
                      L"Personalize",
                      0, KEY_READ, &key) == ERROR_SUCCESS) {
        if (RegQueryValueExW(key, L"SystemUsesLightTheme", nullptr, nullptr,
                             reinterpret_cast<BYTE*>(&value),
                             &size) != ERROR_SUCCESS) {
            size = sizeof(value);
            RegQueryValueExW(key, L"AppsUseLightTheme", nullptr, nullptr,
                             reinterpret_cast<BYTE*>(&value), &size);
        }
        RegCloseKey(key);
    }
    return value != 0;
}
// <<< win10-skin: colour scheme <<<

const Theme* GetSelectedTheme(bool useNewLayoutVariant) {
    // Skin Windows 10 nella variante "ClassicStartMenu" sul layout normale di Windows 11:
    // le varianti per il nuovo layout (newLayoutSideBySide) producono un tema sbagliato.
    useNewLayoutVariant = false;
    PCWSTR themeName = Wh_GetStringSetting(L"theme");
    PCWSTR schemeName = Wh_GetStringSetting(L"themeScheme");

    bool useLightTheme;
    if (wcscmp(schemeName, L"light") == 0) {
        useLightTheme = true;
    } else if (wcscmp(schemeName, L"dark") == 0) {
        useLightTheme = false;
    } else {
        // Auto: follow the Windows app theme.
        useLightTheme = IsSystemLightTheme();
    }

    const Theme* theme = nullptr;
    if (wcscmp(themeName, L"Windows10") == 0) {
        theme = useLightTheme
                    ? (useNewLayoutVariant
                           ? &g_themeWindows10_Light
                           : &g_themeWindows10_Light_variant_ClassicStartMenu)
                    : (useNewLayoutVariant
                           ? &g_themeWindows10
                           : &g_themeWindows10_variant_ClassicStartMenu);
    } else if (wcscmp(themeName, L"Windows10_variant_Minimal") == 0) {
        theme = useLightTheme
                    ? (useNewLayoutVariant
                           ? &g_themeWindows10_Light_variant_Minimal
                           : &g_themeWindows10_Light_variant_Minimal_ClassicStartMenu)
                    : (useNewLayoutVariant
                           ? &g_themeWindows10_variant_Minimal
                           : &g_themeWindows10_variant_Minimal_ClassicStartMenu);
    }

    Wh_FreeStringSetting(themeName);
    Wh_FreeStringSetting(schemeName);
    return theme;
}

// The skin of the taskbar jump lists, selected by its own setting. The jump
// lists are drawn by the shell processes, so it is not part of the Start menu
// skin selection: "None" leaves them to Windows.
bool IsJumpListsEnabled() {
    PCWSTR jumpLists = Wh_GetStringSetting(L"jumpLists");
    bool enabled = wcscmp(jumpLists, L"Windows10") == 0;
    Wh_FreeStringSetting(jumpLists);
    return enabled;
}

// The shell flyout skin is independent of the jump-list theme. It touches only
// the XAML templates below when they exist in ShellExperienceHost/ShellHost.
bool IsShellFlyoutsEnabled() {
    PCWSTR shellFlyouts = Wh_GetStringSetting(L"shellFlyouts");
    bool enabled = wcscmp(shellFlyouts, L"Windows10") == 0;
    Wh_FreeStringSetting(shellFlyouts);
    return enabled;
}

