// desktop button (Show desktop / Peek at desktop) and the clock (Adjust date/time
// / Customize notification icons). Explorer's own ids for the first two are
// 0x1A2D and 0x1A2E; the mod uses its own so that the two never mix.
#define IDM_MOD_PEEK          0x7C75
#define IDM_MOD_ADJUSTDATETIME 0x7C76
#define IDM_MOD_NOTIFYICONS   0x7C77
#define IDM_MOD_SEARCH_HIDDEN  0x7C7A
#define IDM_MOD_SEARCH_ICON    0x7C7B
#define IDM_MOD_SEARCH_BOX     0x7C7C

static bool IsSeparatorItem(HMENU menu, int pos) {
    MENUITEMINFOW mii = {};
    mii.cbSize = sizeof(mii);
    mii.fMask = MIIM_FTYPE;
    return menu && GetMenuItemInfoW(menu, pos, TRUE, &mii) && (mii.fType & MFT_SEPARATOR);
}

