    DWORD retryAt   = 0;       // pausa dopo aver provato tutti i metodi
    bool  diagDone  = false;   // la riga di diagnosi e' gia' stata scritta
    bool  fixedDone = false;   // le correzioni una volta sola
    bool  cleanDone = false;   // pulizia del pulsante fantasma gia' fatta
    bool  blocked   = false;   // superficie di sistema: nessun pulsante, mai
    std::wstring aumid;        // v12: AppUserModel ID trovato per questa finestra
    DWORD aumidAt   = 0;       // v16: quando ritentare se manca ancora
